Error Response Body
<metadata name="ResponseBody" value='@{
    var body = ((IResponse)context.Response)?.Body?.As(preserveContent: true);
    return !string.IsNullOrWhiteSpace(body) ? body : "";
}' />
<metadata name="ResponseStatusCode" value='@{
    var statusCode = context.Response?.StatusCode.ToString();
    return !string.IsNullOrWhiteSpace(statusCode) ? statusCode : "";
}' />
<metadata name="ResponseStatusReason" value='@{
    var statusReason = context.Response?.StatusReason?.ToString();
    return !string.IsNullOrWhiteSpace(statusReason) ? statusReason : "";
}' />
